package com.training.accounting.customer;
import com.training.accounting.user.AppUser; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/customers") public class CustomerController { private final CustomerRepository r; public CustomerController(CustomerRepository r){this.r=r;} public record Req(@NotBlank String name,@Email String email,String phone,String gstin,@Pattern(regexp="ACTIVE|INACTIVE") String status){} private Long bid(Authentication a){return ((AppUser)a.getDetails()).getBusinessId();} @GetMapping public List<Customer> list(Authentication a){return r.findByBusinessIdOrderByIdDesc(bid(a));} @PostMapping public ResponseEntity<Customer> create(@Valid @RequestBody Req q,Authentication a){Customer c=new Customer();c.setBusinessId(bid(a));apply(c,q);return ResponseEntity.status(201).body(r.save(c));} @PutMapping("/{id}") public Customer update(@PathVariable Long id,@Valid @RequestBody Req q,Authentication a){Customer c=r.findByIdAndBusinessId(id,bid(a)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));apply(c,q);return r.save(c);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,Authentication a){Customer c=r.findByIdAndBusinessId(id,bid(a)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));r.delete(c);} private void apply(Customer c,Req q){c.setName(q.name());c.setEmail(q.email());c.setPhone(q.phone());c.setGstin(q.gstin());c.setStatus(q.status()==null?"ACTIVE":q.status());} }
